<?php
declare(strict_types=1);
function editorScreens():array{return ['home'=>'Página inicial','contact'=>'Contato','sponsors'=>'Para empresas','how'=>'Como funciona','donations'=>'Doações','rules'=>'Regras','privacy'=>'Privacidade','login'=>'Login usuário','register'=>'Cadastro','forgot'=>'Recuperar senha','reset'=>'Nova senha','account'=>'Minha conta','publish'=>'Anunciar','my-listings'=>'Meus anúncios','listing'=>'Detalhe do anúncio','propose'=>'Fazer proposta','inbox'=>'Conversas','thread'=>'Conversa aberta','matches'=>'Matches','close-account'=>'Encerrar conta','admin-login'=>'Login administrativo'];}
function ensureVisualEdits():void{static $done=false;if($done)return;sql("CREATE TABLE IF NOT EXISTS visual_edits(screen VARCHAR(30) NOT NULL,device VARCHAR(10) NOT NULL,element_key VARCHAR(500) NOT NULL,payload TEXT NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(screen,device,element_key))");$done=true;}
function visualConfig(string $screen):array{if(!isset(editorScreens()[$screen]))return [];ensureVisualEdits();$out=[];foreach(sql('SELECT device,element_key,payload FROM visual_edits WHERE screen=?',[$screen])->fetchAll() as $row)$out[$row['device']][$row['element_key']]=json_decode($row['payload'],true);return $out;}
function saveVisualEdit():never{
 requireAdmin();checkCsrf();$screen=(string)($_POST['screen']??'');$device=(string)($_POST['device']??'');$key=(string)($_POST['key']??'');
 if(!isset(editorScreens()[$screen])||!in_array($device,['desktop','mobile'],true)||!preg_match('~^[a-z0-9:/-]{1,500}$~',$key))throw new RuntimeException('Seleção inválida.');
 $data=json_decode((string)($_POST['payload']??''),true);if(!is_array($data))throw new RuntimeException('Alteração inválida.');$clean=['styles'=>[]];
 if(isset($data['text'])){if(!is_string($data['text'])||mb_strlen($data['text'])>5000)throw new RuntimeException('Texto muito longo.');$clean['text']=$data['text'];}
 foreach($data['styles']??[] as $name=>$value){if(!in_array($name,['fontSize','lineHeight','width','height','translateX','translateY'],true)||!is_numeric($value)||!is_finite((float)$value))throw new RuntimeException('Aparência inválida.');$number=(float)$value;if(abs($number)>3000||($name==='fontSize'&&($number<8||$number>200))||($name==='lineHeight'&&($number<.5||$number>4))||in_array($name,['width','height'],true)&&$number<1)throw new RuntimeException('Valor fora do limite.');$clean['styles'][$name]=$number;}
 ensureVisualEdits();tx(function()use($screen,$device,$key,$clean){sql('DELETE FROM visual_edits WHERE screen=? AND device=? AND element_key=?',[$screen,$device,$key]);if(!isset($_POST['reset']))sql('INSERT INTO visual_edits(screen,device,element_key,payload,updated_at) VALUES(?,?,?,?,?)',[$screen,$device,$key,json_encode($clean,JSON_UNESCAPED_UNICODE),now()]);});audit('visual_edit',0,$screen.' / '.$device.' / '.$key);header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;
}
function renderAdminLogin():void{if(!isset($_GET['editor_preview'])&&currentUser()&&currentUser()['role']==='ADMIN')go('admin');echo '<section class="form-panel"><p class="eyebrow">ACESSO RESTRITO</p><h1>Administração Trokar.ia</h1><p>Entre com sua conta de administrador.</p>';beginForm('admin_login');field('email','E-mail','','email',max:190);field('password','Senha','','password',max:200);submit('Entrar no admin');echo '<a href="'.e(url('forgot')).'">Recuperar senha</a></section>';}
function renderVisualEditor():void{
 requireAdmin();$screen=(string)($_GET['screen']??'home');if(!isset(editorScreens()[$screen]))$screen='home';$params=['editor_preview'=>1];
 if(in_array($screen,['listing','propose','publish'],true)){$id=sql("SELECT id FROM listings WHERE status='ACTIVE' ORDER BY id DESC LIMIT 1")->fetchColumn();if($id)$params['id']=(int)$id;}
 if($screen==='thread'){$u=currentUser();$id=sql('SELECT id FROM proposals WHERE sender_id=? OR recipient_id=? ORDER BY id DESC LIMIT 1',[$u['id'],$u['id']])->fetchColumn();if($id)$params['id']=(int)$id;}
 ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editor por clique — Trokar.ia</title><link rel="stylesheet" href="assets/editor.css?v=1"></head><body><aside><a href="<?=e(url('admin'))?>">← Voltar ao admin</a><h1>Editor por clique</h1><label>Tela<select id="screen"><?php foreach(editorScreens() as $key=>$name):?><option value="<?=e($key)?>" <?=$key===$screen?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></label><div class="devices"><button data-device="desktop" aria-pressed="true">Computador</button><button data-device="mobile" aria-pressed="false">Celular</button></div><p id="target">Clique em um texto, botão ou bloco na tela.</p><label>Texto<textarea id="text" disabled></textarea></label><div class="fields"><?php foreach(['fontSize'=>'Fonte (px)','lineHeight'=>'Entrelinhas','width'=>'Largura (px)','height'=>'Altura (px)','translateX'=>'Horizontal (px)','translateY'=>'Vertical (px)'] as $key=>$name):?><label><?=e($name)?><input data-style="<?=e($key)?>" type="number" step="<?=$key==='lineHeight'?'0.1':'1'?>" disabled></label><?php endforeach;?></div><button id="parent" disabled>Selecionar bloco acima</button><button id="save" disabled>Salvar alteração</button><button id="reset" disabled>Restaurar este elemento</button><p id="status" role="status">Computador e celular são salvos separadamente. Arraste as bolinhas para largura e altura.</p><p>Dados pessoais e informações das negociações permitem ajustar aparência, sem substituir conteúdo. Telas que exigem um anúncio ou conversa precisam de conteúdo disponível para prévia.</p></aside><main><div id="canvas"><iframe id="preview" title="Prévia editável" src="<?=e(url($screen,$params))?>"></iframe></div></main><script id="editor-data" type="application/json"><?=json_encode(['screen'=>$screen,'csrf'=>csrf()],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="assets/editor.js?v=1"></script></body></html><?php
}
